content:
:root {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  background-color: #f0f4f8;
  color: #333;
  margin: 0;
  padding: 0;
}

body {
  margin: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.app-container {
  width: 100%;
  max-width: 600px;
  margin: 0 auto;
  padding: 20px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.header {
  margin-bottom: 20px;
  text-align: center;
}

.title {
  font-size: 2rem;
  color: #2563eb;
  margin: 0;
  font-weight: 700;
}

.game-box {
  background: #ffffff;
  padding: 30px;
  border-radius: 16px;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.05);
  width: 100%;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.stats-row {
  display: flex;
  justify-content: space-between;
  font-size: 1.2rem;
  font-weight: 600;
  color: #4b5563;
  background: #f9fafb;
  padding: 12px 20px;
  border-radius: 8px;
}

.timer {
  color: #dc2626;
}

.score {
  color: #16a34a;
}

.word-card {
  background: #eff6ff;
  border: 2px solid #bfdbfe;
  border-radius: 12px;
  padding: 24px;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.japanese-text {
  font-size: 1.5rem;
  font-weight: 700;
  color: #1e3a8a;
}

.romaji-text {
  font-size: 1.8rem;
  font-family: monospace;
  font-weight: 700;
  color: #2563eb;
  letter-spacing: 2px;
}

.input-field {
  width: 100%;
  padding: 16px;
  font-size: 1.5rem;
  font-family: monospace;
  border: 2px solid #d1d5db;
  border-radius: 8px;
  box-sizing: border-box;
  text-align: center;
  outline: none;
  transition: border-color 0.2s;
}

.input-field:focus {
  border-color: #2563eb;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.2);
}

.btn {
  padding: 12px 24px;
  font-size: 1.1rem;
  font-weight: 600;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: #2563eb;
  color: #ffffff;
}

.btn-primary:hover {
  background-color: #1d4ed8;
}

.result-modal {
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 20px;
  padding: 10px;
}

.result-modal h2 {
  font-size: 2rem;
  margin: 0;
  color: #1f2937;
}

.result-modal p {
  font-size: 1.2rem;
  margin: 0;
  color: #4b5563;
}

.restart-btn {
  background-color: #16a34a;
  color: white;
  font-size: 1.2rem;
  padding: 14px 28px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-weight: 700;
  transition: background-color 0.2s, transform 0.1s;
}

.restart-btn:hover {
  background-color: #15803d;
}

.restart-btn:active {
  transform: scale(0.98);
}

export interface WordItem {
  id: string;
  japanese: string;
  romaji: string;
}

export type GameStatus = 'idle' | 'playing' | 'finished';

import { useState } from 'react';
import { GameStatus } from './types';
import GameArea from './components/GameArea';
import './index.css';

export default function App() {
  const [gameStatus, setGameStatus] = useState<GameStatus>('idle');
  const [score, setScore] = useState<number>(0);
  const [timeLeft, setTimeLeft] = useState<number>(60);
  const [totalTypedChars, setTotalTypedChars] = useState<number>(0);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">ローマ字タイピングゲーム</h1>
      </header>
      <GameArea
        gameStatus={gameStatus}
        setGameStatus={setGameStatus}
        score={score}
        setScore={setScore}
        timeLeft={timeLeft}
        setTimeLeft={setTimeLeft}
        totalTypedChars={totalTypedChars}
        setTotalTypedChars={setTotalTypedChars}
      />
    </div>
  );
}

import { useState, useEffect, useRef, ChangeEvent } from 'react';
import { GameStatus, WordItem } from '../types';

interface GameAreaProps {
  gameStatus: GameStatus;
  setGameStatus: (status: GameStatus) => void;
  score: number;
  setScore: (score: number) => void;
  timeLeft: number;
  setTimeLeft: React.Dispatch<React.SetStateAction<number>>;
  totalTypedChars: number;
  setTotalTypedChars: (chars: number) => void;
}

const WORDS: WordItem[] = [
  { id: '1', japanese: '猫', romaji: 'neko' },
  { id: '2', japanese: '犬', romaji: 'inu' },
  { id: '3', japanese: 'りんご', romaji: 'ringo' },
  { id: '4', japanese: '本', romaji: 'hon' },
  { id: '5', japanese: '車', romaji: 'kuruma' },
  { id: '6', japanese: 'パソコン', romaji: 'pasokon' },
  { id: '7', japanese: 'プログラミング', romaji: 'puroguramingu' },
  { id: '8', japanese: 'タイピング', romaji: 'taipingu' },
  { id: '9', japanese: '未来', romaji: 'mirai' },
  { id: '10', japanese: '桜', romaji: 'sakura' },
  { id: '11', japanese: '空', romaji: 'sora' },
  { id: '12', japanese: '海', romaji: 'umi' },
];

export default function GameArea({
  gameStatus,
  setGameStatus,
  score,
  setScore,
  timeLeft,
  setTimeLeft,
  totalTypedChars,
  setTotalTypedChars,
}: GameAreaProps) {
  const [currentWordIndex, setCurrentWordIndex] = useState<number>(0);
  const [inputVal, setInputVal] = useState<string>('');
  const inputRef = useRef<HTMLInputElement>(null);

  const currentWord = WORDS[currentWordIndex] || WORDS[0];

  const handleStart = () => {
    setGameStatus('playing');
    setScore(0);
    setTimeLeft(60);
    setTotalTypedChars(0);
    setCurrentWordIndex(Math.floor(Math.random() * WORDS.length));
    setInputVal('');
  };

  useEffect(() => {
    if (gameStatus !== 'playing') return;

    if (timeLeft <= 0) {
      setGameStatus('finished');
      return;
    }

    const timer = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          clearInterval(timer);
          setGameStatus('finished');
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [gameStatus, timeLeft, setGameStatus, setTimeLeft]);

  useEffect(() => {
    if (gameStatus === 'playing') {
      inputRef.current?.focus();
    }
  }, [gameStatus, currentWordIndex]);

  const handleInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    if (gameStatus !== 'playing') return;
    const val = e.target.value;
    setInputVal(val);

    if (val === currentWord.romaji) {
      setScore(score + 1);
      setTotalTypedChars(totalTypedChars + currentWord.romaji.length);
      setInputVal('');
      const nextIndex = Math.floor(Math.random() * WORDS.length);
      setCurrentWordIndex(nextIndex);
    }
  };

  return (
    <div className="game-box">
      {gameStatus === 'idle' && (
        <div style={{ textAlign: 'center', display: 'flex', flexDirection: 'column', gap: '20px' }}>
          <h2>60秒間で何文字打てるかな？</h2>
          <p>表示される単語のローマ字を正確に入力していこう！</p>
          <button className="btn btn-primary" onClick={handleStart}>
            ゲームスタート
          </button>
        </div>
      )}

      {gameStatus === 'playing' && (
        <>
          <div className="stats-row">
            <div>残り時間: <span className="timer">{timeLeft}秒</span></div>
            <div>正解数: <span className="score">{score}問</span></div>
          </div>

          <div className="word-card">
            <div className="japanese-text">{currentWord.japanese}</div>
            <div className="romaji-text">{currentWord.romaji}</div>
          </div>

          <input
            ref={inputRef}
            type="text"
            className="input-field"
            value={inputVal}
            onChange={handleInputChange}
            placeholder="ここに入力..."
            autoFocus
            autoCapitalize="none"
            autoComplete="off"
            spellCheck="false"
          />
        </>
      )}

      {gameStatus === 'finished' && (
        <div className="result-modal">
          <h2>タイムアップ！</h2>
          <p>お疲れ様でした！</p>
          <p>正解数: <strong>{score} 問</strong></p>
          <p>合計打鍵文字数: <strong>{totalTypedChars} 文字</strong></p>
          <button className="restart-btn" onClick={handleStart}>
            もう一度プレイする
          </button>
        </div>
      )}
    </div>
  );
}
